<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Index/admin_money_list')}" class="on">业务员流水</a>									</ul>			</div>						<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th><a href="{pigcms{:U('User/index',array('sort'=>'uid'))}" style="color:blue;">商家ID</a></th>								<th>商家名称</th>								<th>商家手机</th>								<th class="textcenter">商家流水总额</th>								<th class="textcenter">流水明细</th>														</tr>						</thead>						<tbody>							<if condition="is_array($merchant_list)">								<volist name="merchant_list" id="vo">									<tr>										<td>{pigcms{$vo.mer_id}</td>										<td>{pigcms{$vo.name}</td>										<td>{pigcms{$vo.phone}</td>										<td class="textcenter">{pigcms{$config['Currency_symbol']}{pigcms{$vo.spread_money|floatval=###}</td>										<td class="textcenter">										<a href="{pigcms{:U('Bill/merchant_money_list')}&mer_id={pigcms{$vo.mer_id}" >查看流水详情</a>										</td>																			</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="5">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="5">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script>		 var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('User/export')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>